// Procedural 2D avatar rendering: front-view SVG for cards/nav,
// and face drawing shared with the 3D head texture.

export function drawFace(ctx, w, h, kind) {
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = '#1b1b1b';
  ctx.strokeStyle = '#1b1b1b';
  ctx.lineCap = 'round';
  const ex = w * 0.30, ex2 = w * 0.70, ey = h * 0.40;
  const er = w * 0.055;

  const eye = (x, y, r) => { ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill(); };
  const arcMouth = (open, flip = false) => {
    ctx.lineWidth = w * 0.05;
    ctx.beginPath();
    if (flip) ctx.arc(w / 2, h * 0.78, w * 0.18, Math.PI * 1.15, Math.PI * 1.85);
    else ctx.arc(w / 2, h * 0.58, w * 0.18, Math.PI * 0.15, Math.PI * 0.85);
    ctx.stroke();
    if (open) { ctx.beginPath(); ctx.arc(w / 2, h * 0.68, w * 0.13, 0, 7); ctx.fill(); }
  };

  switch (kind) {
    case 'happy':
      eye(ex, ey, er); eye(ex2, ey, er);
      ctx.beginPath(); ctx.arc(w / 2, h * 0.58, w * 0.2, 0.1, Math.PI - 0.1); ctx.fill();
      break;
    case 'wink':
      eye(ex, ey, er);
      ctx.lineWidth = w * 0.045;
      ctx.beginPath(); ctx.moveTo(ex2 - er * 1.6, ey); ctx.lineTo(ex2 + er * 1.6, ey); ctx.stroke();
      arcMouth(false);
      break;
    case 'cool':
      ctx.fillRect(w * 0.16, ey - er * 2.2, w * 0.28, er * 4); // left lens
      ctx.fillRect(w * 0.56, ey - er * 2.2, w * 0.28, er * 4); // right lens
      ctx.fillRect(w * 0.42, ey - er * 0.8, w * 0.16, er * 1.2); // bridge
      ctx.lineWidth = w * 0.05;
      ctx.beginPath(); ctx.moveTo(w * 0.36, h * 0.68); ctx.lineTo(w * 0.64, h * 0.66); ctx.stroke();
      break;
    case 'grr':
      ctx.lineWidth = w * 0.05;
      ctx.beginPath(); ctx.moveTo(ex - er * 2, ey - er * 2.4); ctx.lineTo(ex + er * 1.5, ey - er * 0.8); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(ex2 + er * 2, ey - er * 2.4); ctx.lineTo(ex2 - er * 1.5, ey - er * 0.8); ctx.stroke();
      eye(ex, ey, er); eye(ex2, ey, er);
      arcMouth(false, true);
      break;
    case 'surprised':
      eye(ex, ey, er * 1.4); eye(ex2, ey, er * 1.4);
      ctx.beginPath(); ctx.arc(w / 2, h * 0.68, w * 0.1, 0, 7); ctx.fill();
      break;
    case 'sleepy':
      ctx.lineWidth = w * 0.045;
      ctx.beginPath(); ctx.moveTo(ex - er * 1.6, ey); ctx.lineTo(ex + er * 1.6, ey); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(ex2 - er * 1.6, ey); ctx.lineTo(ex2 + er * 1.6, ey); ctx.stroke();
      ctx.beginPath(); ctx.arc(w / 2, h * 0.66, w * 0.07, 0, 7); ctx.fill();
      break;
    default: // smile
      eye(ex, ey, er); eye(ex2, ey, er);
      arcMouth(false);
  }
}

export function faceDataURL(kind, size = 96, bg = null) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  if (bg) { ctx.fillStyle = bg; ctx.fillRect(0, 0, size, size); }
  drawFace(ctx, size, size, kind);
  return c.toDataURL();
}

// Front-view blocky avatar as inline SVG.
export function avatarSVG(avatar, size = 64) {
  const bc = (avatar && avatar.bodyColors) || {};
  const head = bc.head || '#ffd23f', torso = bc.torso || '#2a7de1';
  const la = bc.leftArm || head, ra = bc.rightArm || head;
  const ll = bc.leftLeg || '#37474f', rl = bc.rightLeg || '#37474f';
  const face = faceDataURL((avatar && avatar.face || 'face_smile').replace('face_', ''), 48);
  // hat hint: a simple shape on top if any hat equipped
  const hat = avatar && avatar.hat
    ? `<rect x="22" y="2" width="20" height="7" rx="2" fill="#333"/><rect x="27" y="-4" width="10" height="8" rx="2" fill="#555"/>`
    : '';
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 84" width="${size}" height="${size * 84 / 64}">
    ${hat}
    <rect x="24" y="6" width="16" height="14" rx="4" fill="${head}"/>
    <image href="${face}" x="25" y="7" width="14" height="12"/>
    <rect x="20" y="22" width="24" height="26" rx="3" fill="${torso}"/>
    <rect x="11" y="22" width="8" height="24" rx="3" fill="${la}"/>
    <rect x="45" y="22" width="8" height="24" rx="3" fill="${ra}"/>
    <rect x="21" y="50" width="10" height="26" rx="3" fill="${ll}"/>
    <rect x="33" y="50" width="10" height="26" rx="3" fill="${rl}"/>
  </svg>`;
}
